/** @format */
"use client";

import { useState } from "react";
import Image from "next/image";
import { Pencil, Check, X } from "lucide-react";
import { Card, CardHeader, CardTitle, CardContent, CardFooter } from "@components/ui/card";
export const DropZone = () => {
	const [preview, setPreview] = useState(null);
	const [isDragging, setIsDragging] = useState(false);
	const [images, setImages] = useState([]);
	const handleDragOver = (e) => {
		e.preventDefault();
		setIsDragging(true);
	};

	const handleDragLeave = (e) => {
		e.preventDefault();
		setIsDragging(false);
	};

	const handleDrop = (e) => {
		e.preventDefault();
		setIsDragging(false);
		const files = Array.from(e.dataTransfer.files);
		displayPreview(files);
	};

	const handleFileChange = (e) => {
		const files = Array.from(e.target.files);
		displayPreview(files);
	};

	const displayPreview = (files) => {
		const newImages = files.map((file) => {
			const reader = new FileReader();

			return new Promise((resolve) => {
				reader.onload = () => {
					resolve({ preview: reader.result, name: file.name });
				};
				reader.readAsDataURL(file);
			});
		});
		Promise.all(newImages).then((results) => {
			setImages((prevPreviews) => [...prevPreviews, ...results]);
		});
	};

	return (
		<div
			className={`w-[400px] relative border-2 border-gray-300 border-dashed rounded-lg p-6 ${isDragging ? "border-indigo-600" : ""}`}
			onDragOver={handleDragOver}
			onDragLeave={handleDragLeave}
			onDrop={handleDrop}
		>
			<input
				type="file"
				className="absolute inset-0 w-full h-full opacity-0 z-50"
				onChange={handleFileChange}
			/>
			<div className="text-center">
				<Image
					className="mx-auto h-12 w-12"
					src="https://www.svgrepo.com/show/357902/image-upload.svg"
					alt="Upload icon"
					width={250}
					height={250}
				/>
				<h3 className="mt-2 text-sm font-medium text-gray-900">
					<label className="relative cursor-pointer">
						<span>Drag and drop</span>
						<span className="text-indigo-600"> or browse</span>
						<span> to upload</span>
						<input
							id="file-upload"
							name="file-upload"
							type="file"
							className="sr-only"
						/>
					</label>
				</h3>
				<p className="mt-1 text-xs text-gray-500">PNG, JPG, GIF up to 10MB</p>
			</div>

			{images.map(({ preview, name }, index) => (
				<div key={index} className="text-center">
					<Image
						src={preview}
						width={250}
						height={250}
						className="mt-4 mx-auto max-h-40"
						alt="Preview"
					/>
					<p className="mt-2 text-xs text-gray-500">{name}</p> {/* Display filename */}
				</div>
			))}
		</div>
	);
};
const ImageCard = ({ preview, name }) => {
	return (
		<Card className="w-full max-w-md mx-auto overflow-hidden border-2 border-gray-200 rounded-lg transition-all duration-300 hover:shadow-lg">
			<CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
				<CardTitle className="text-sm font-medium">Image Editor</CardTitle>
				{!isEditing && (
					<Button variant="ghost" size="icon" onClick={handleEdit}>
						<Pencil className="h-4 w-4" />
					</Button>
				)}
			</CardHeader>
			<CardContent>
				<div className="relative w-full h-48 mb-4">
					<Image
						src={imageSrc}
						alt={filename}
						layout="fill"
						objectFit="cover"
						className="rounded-md"
					/>
				</div>
				{isEditing ? (
					<div className="space-y-2">
						<Label htmlFor="filename">Filename</Label>
						<Input
							id="filename"
							value={tempFilename}
							onChange={(e) => setTempFilename(e.target.value)}
							className="w-full"
						/>
					</div>
				) : (
					<p className="text-sm font-medium break-all">{filename}</p>
				)}
			</CardContent>
			{isEditing && (
				<CardFooter className="flex justify-end space-x-2">
					<Button variant="outline" size="sm" onClick={handleCancel}>
						<X className="h-4 w-4 mr-2" />
						Cancel
					</Button>
					<Button variant="default" size="sm" onClick={handleSave}>
						<Check className="h-4 w-4 mr-2" />
						Save
					</Button>
				</CardFooter>
			)}
		</Card>
	);
};
export default DropZone;
